-- Printed posts - Eight, put back fresh under a new id (Dani, 25 Oct). The old
-- tmpl-mk-print8 kept reopening as an earlier edit at 1080 x 1440: a browser's
-- saved copy and the layouts saved for other sizes are tied to a design's id,
-- and the reset couldn't reach them. A new id starts with neither. 1600 x 2000.

delete from public.templates where id = 'tmpl-mk-print8';

insert into public.templates (id, name, category, thumb_url, canvas, elements, status, sort_order, kind)
