on conflict (id) do update set canvas = excluded.canvas, elements = excluded.elements, thumb_url = excluded.thumb_url, status = excluded.status, size_variants = '{}'::jsonb;

select id, name, status, canvas->>'width' as width, canvas->>'height' as height, jsonb_array_length(elements) as screens
  from public.templates where name ilike '%printed posts%' order by name;
